CREATE TYPE public.app_role AS ENUM ('staff', 'representative');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, company_id text, CHECK ((role='staff' AND company_id IS NULL) OR (role='representative' AND company_id IS NOT NULL)), UNIQUE(company_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.is_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='staff') $$;
CREATE FUNCTION public.can_manage_company(cid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role='staff' OR (role='representative' AND company_id=cid))) $$;
REVOKE ALL ON FUNCTION public.is_staff() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_staff() TO authenticated;
REVOKE ALL ON FUNCTION public.can_manage_company(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_manage_company(text) TO authenticated;
CREATE TABLE public.company_public_profiles (company_id text PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', interests text[] NOT NULL DEFAULT '{}', technologies text[] NOT NULL DEFAULT '{}', priorities text NOT NULL DEFAULT '', provenance text NOT NULL DEFAULT 'Illustrative demo baseline', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.company_public_profiles TO anon, authenticated; GRANT ALL ON public.company_public_profiles TO service_role;
ALTER TABLE public.company_public_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_profiles_read ON public.company_public_profiles FOR SELECT TO anon, authenticated USING(true);
CREATE TABLE public.company_private_profiles (company_id text PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', interests text[] NOT NULL DEFAULT '{}', technologies text[] NOT NULL DEFAULT '{}', priorities text NOT NULL DEFAULT '', private_notes text NOT NULL DEFAULT '', review_status text NOT NULL DEFAULT 'Not reviewed' CHECK(review_status IN ('Not reviewed','Sent for review','Reviewed')), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.company_private_profiles TO authenticated; GRANT ALL ON public.company_private_profiles TO service_role;
ALTER TABLE public.company_private_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY private_profiles_read ON public.company_private_profiles FOR SELECT TO authenticated USING(public.can_manage_company(company_id));
CREATE TABLE public.profile_review_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id text NOT NULL, sender_id uuid NOT NULL, recipient_id uuid NOT NULL, status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Reviewed')), created_at timestamptz NOT NULL DEFAULT now(), reviewed_at timestamptz);
GRANT SELECT ON public.profile_review_requests TO authenticated; GRANT ALL ON public.profile_review_requests TO service_role;
ALTER TABLE public.profile_review_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY review_read ON public.profile_review_requests FOR SELECT TO authenticated USING(public.is_staff() OR recipient_id=auth.uid());
CREATE FUNCTION public.create_account_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER account_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_account_profile();
CREATE FUNCTION public.save_company_profile(cid text, profile_data jsonb, publish_fields text[] DEFAULT '{}') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE old_public public.company_public_profiles%ROWTYPE;
BEGIN
IF NOT public.can_manage_company(cid) THEN RAISE EXCEPTION 'Not authorised to edit this company'; END IF;
IF NOT cid=ANY(ARRAY['nord','ocean','aether','modul','baltic','pulse','ericsson']) THEN RAISE EXCEPTION 'Unknown company'; END IF;
IF length(coalesce(profile_data->>'name','')) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Company name is required'; END IF;
INSERT INTO public.company_private_profiles(company_id,name,description,interests,technologies,priorities,private_notes,review_status) VALUES(cid,profile_data->>'name',coalesce(profile_data->>'description',''),ARRAY(SELECT jsonb_array_elements_text(coalesce(profile_data->'interests','[]'::jsonb))),ARRAY(SELECT jsonb_array_elements_text(coalesce(profile_data->'technologies','[]'::jsonb))),coalesce(profile_data->>'priorities',''),coalesce(profile_data->>'private_notes',''),'Reviewed') ON CONFLICT(company_id) DO UPDATE SET name=excluded.name,description=excluded.description,interests=excluded.interests,technologies=excluded.technologies,priorities=excluded.priorities,private_notes=excluded.private_notes,review_status='Reviewed',updated_at=now();
IF cardinality(publish_fields)>0 THEN
IF NOT publish_fields <@ ARRAY['name','description','interests','technologies','priorities'] THEN RAISE EXCEPTION 'Invalid public fields'; END IF;
SELECT * INTO old_public FROM public.company_public_profiles WHERE company_id=cid;
IF NOT FOUND THEN RAISE EXCEPTION 'Published baseline is not available'; END IF;
UPDATE public.company_public_profiles SET name=CASE WHEN 'name'=ANY(publish_fields) THEN profile_data->>'name' ELSE name END,description=CASE WHEN 'description'=ANY(publish_fields) THEN profile_data->>'description' ELSE description END,interests=CASE WHEN 'interests'=ANY(publish_fields) THEN ARRAY(SELECT jsonb_array_elements_text(profile_data->'interests')) ELSE interests END,technologies=CASE WHEN 'technologies'=ANY(publish_fields) THEN ARRAY(SELECT jsonb_array_elements_text(profile_data->'technologies')) ELSE technologies END,priorities=CASE WHEN 'priorities'=ANY(publish_fields) THEN profile_data->>'priorities' ELSE priorities END,provenance='Company-provided information',updated_at=now() WHERE company_id=cid;
END IF;
IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='representative' AND company_id=cid) THEN UPDATE public.profile_review_requests SET status='Reviewed',reviewed_at=now() WHERE company_id=cid AND recipient_id=auth.uid() AND status='Pending'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.save_company_profile(text,jsonb,text[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_company_profile(text,jsonb,text[]) TO authenticated;
CREATE FUNCTION public.send_company_review(cid text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient uuid; request_id uuid; BEGIN
IF NOT public.is_staff() THEN RAISE EXCEPTION 'Staff access required'; END IF;
SELECT user_id INTO recipient FROM public.user_roles WHERE role='representative' AND company_id=cid;
IF recipient IS NULL THEN RAISE EXCEPTION 'This company does not have a registered representative account yet'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.company_private_profiles WHERE company_id=cid) THEN RAISE EXCEPTION 'Save a company profile before requesting review'; END IF;
INSERT INTO public.profile_review_requests(company_id,sender_id,recipient_id) VALUES(cid,auth.uid(),recipient) RETURNING id INTO request_id;
UPDATE public.company_private_profiles SET review_status='Sent for review',updated_at=now() WHERE company_id=cid; RETURN request_id;
END $$;
REVOKE ALL ON FUNCTION public.send_company_review(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.send_company_review(text) TO authenticated;
CREATE FUNCTION public.company_review_recipient(cid text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_staff() THEN RAISE EXCEPTION 'Staff access required'; END IF; RETURN (SELECT coalesce(nullif(p.display_name,''),'Registered company account') FROM public.user_roles r JOIN public.profiles p ON p.id=r.user_id WHERE r.company_id=cid AND r.role='representative'); END $$;
REVOKE ALL ON FUNCTION public.company_review_recipient(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.company_review_recipient(text) TO authenticated;